param([int]$Worlds = 1,[string]$Model = $env:OPENAI_MODEL)
if ([string]::IsNullOrWhiteSpace($Model)) { $Model = "gpt-4.1" }
$apiKey = $env:OPENAI_API_KEY; if (-not $apiKey) { Write-Error "OPENAI_API_KEY missing"; exit 1 }
$Root = Split-Path -Parent $PSScriptRoot
$dmDir = Join-Path $Root 'pages/apps/alexandria/dm'
$null = New-Item -ItemType Directory -Path $dmDir -Force
$sys = @"
You are ALEXANDRIA, a Dungeon Master AI for collaborative storytelling.
Output STRICT JSON only.
For each world, produce a compact DM pack with this schema:
{
 "world": {"id": string, "title": string, "genre": string, "tone": string,
           "pillars": ["exploration","social","combat"],
           "magic": {"sources":[string],"costs":[string],"limits":[string],"schools":[string]},
           "pantheon":[{"name":string,"domain":string,"taboos":[string]}],
           "cultures":[{"name":string,"values":[string],"tech_level":string}],
           "factions":[{"name":string,"goal":string,"assets":[string]}],
           "geography":{"regions":[{"name":string,"traits":[string]}]},
           "laws":{"taboos":[string],"punishments":[string]}
 },
 "random_tables": {
   "hooks":[{"d":20,"rows":[string]}],
   "npcs":[{"d":20,"rows":[string]}],
   "local_events":[{"d":12,"rows":[string]}]
 },
 "session_seeds": [{"title":string,"setup":string,"twist":string}],
 "house_rules": [{"name":string,"effect":string}],
 "novelization": {"serial_title":string,"season_outline":[{"ep":int,"beat":string}]}
}
"@
$user = "Create {0} DM packs. Keep each field compact but evocative." -f $Worlds
$body = @{ model=$Model; temperature=0.35; messages=@(@{role="system";content=$sys},@{role="user";content=$user}) } | ConvertTo-Json -Depth 6
$headers=@{"Authorization"="Bearer $apiKey";"Content-Type"="application/json"}
try {
  $resp=Invoke-RestMethod -Method Post -Uri "https://api.openai.com/v1/chat/completions" -Headers $headers -Body $body
  $txt=$resp.choices[0].message.content
  if($txt -match '```'){ $txt=($txt -replace '```json','' -replace '```','').Trim() }
  $obj=$txt|ConvertFrom-Json
} catch { Write-Error "Alexandria DM failed: $($_.Exception.Message)"; exit 1 }
$now=(Get-Date).ToUniversalTime().ToString('s')+'Z'
$index = @{ updated=$now; worlds=@() }
$wcount = 0
foreach($pack in $obj){
  $id = if ($pack.world.id){ $pack.world.id } else { "dm-"+([Guid]::NewGuid().ToString("N").Substring(0,8)) }
  $file = "$id.json"
  [IO.File]::WriteAllText((Join-Path $dmDir $file), ($pack|ConvertTo-Json -Depth 16), [Text.Encoding]::UTF8)
  $index.worlds += @{ id=$id; title=$pack.world.title; file=$file }
  $wcount++
}
[IO.File]::WriteAllText((Join-Path $dmDir 'index.json'), ($index|ConvertTo-Json -Depth 12), [Text.Encoding]::UTF8)
Write-Host "Alexandria DM: wrote $wcount packs."

$Root = Split-Path -Parent $PSScriptRoot
$dir = Join-Path $Root 'pages/apps/alexandria/dm'
if (-not (Test-Path $dir)){ Write-Host "No Alexandria DM packs."; exit 0 }
$bad=@()
Get-ChildItem -File $dir -Filter *.json | Where-Object { $_.Name -ne 'index.json' } | ForEach-Object {
  try {
    $j = Get-Content -Raw -Path $_.FullName | ConvertFrom-Json
    if (-not $j.world -or -not $j.random_tables -or -not $j.session_seeds) { $bad += @{file=$_.Name; issue="missing-keys"} }
    elseif (-not $j.world.magic -or -not $j.world.factions) { $bad += @{file=$_.Name; issue="missing-magic-or-factions"} }
  } catch { $bad += @{file=$_.Name; issue="parse-failed"} }
}
if ($bad.Count -gt 0) { Write-Error ("Alexandria validate failed: " + ($bad | ConvertTo-Json -Depth 6)); exit 1 }
Write-Host "Alexandria DM validate OK."

param([string]$WorldName="Avalon",[string]$Tone="high fantasy",[string]$MagicStyle="semi-hard, cost-based",[string]$Model=$env:OPENAI_MODEL)
if([string]::IsNullOrWhiteSpace($Model)){$Model="gpt-4.1-mini"}
$api=$env:OPENAI_API_KEY; if(-not $api){Write-Error "OPENAI_API_KEY missing"; exit 1}
$root=Split-Path -Parent $PSScriptRoot; $base=Join-Path $root 'pages/apps/alexandria/worlds'; New-Item -ItemType Directory -Path $base -Force|Out-Null
function Slug($s){ return ($s -replace '[^a-zA-Z0-9\- ]','' -replace '\s+','-').ToLower() }
$slug = Slug $WorldName; $dir=Join-Path $base $slug; New-Item -ItemType Directory -Path $dir -Force|Out-Null
$out=Join-Path $dir 'world.json'
$sys=@"
You are ALEXANDRIA, a worldbuilding DM partner. Build a concise 'world bible' skeleton for a tabletop campaign.
Include: premise, themes, geography (regions & landmarks), cultures & societies, magic rules ({$MagicStyle}), technology, factions, economy, pantheon, bestiary seeds, quest hooks, session zero boundaries & safety tools, dice prompts.
Output STRICT JSON:
{ world: { name, tone, premise, themes:[string], geography:{regions:[{name,notes}], landmarks:[{name,notes}]}, cultures:[{name,traits}], magic:{sources, costs, limits}, technology:{level,notes}, factions:[{name,agenda,assets}], economy:{currencies,trade}, pantheon:[{name,domain}], bestiary:[{name,role}], hooks:[string], safety_tools:[string], dice_prompts:[string] } }
"@
$user="World name: $WorldName. Tone: $Tone. Keep it tight but gameable."
$hdr=@{"Authorization"="Bearer $api";"Content-Type"="application/json"}
$body=@{model=$Model;temperature=0.35;messages=@(@{role="system";content=$sys},@{role="user";content=$user})}|ConvertTo-Json -Depth 6
try{$r=Invoke-RestMethod -Method Post -Uri "https://api.openai.com/v1/chat/completions" -Headers $hdr -Body $body; $txt=$r.choices[0].message.content; if($txt -match '```'){ $txt=($txt -replace '```json','' -replace '```','').Trim() }; $j=$txt|ConvertFrom-Json }catch{Write-Error "LLM/JSON error: $_"; exit 1}
[IO.File]::WriteAllText($out,($j|ConvertTo-Json -Depth 16),[Text.Encoding]::UTF8); Write-Host "World bible -> $out"

function As-Int {
  [CmdletBinding()]
  param([Parameter(Mandatory=$true)][object]$Value,[switch]$AllowNull)
  if ($null -eq $Value) { if ($AllowNull){return $null} throw "As-Int: Value is null" }
  if ($Value -is [int]) { return [int]$Value }
  if ($Value -is [long]) { return [int][long]$Value }
  if ($Value -is [double] -or $Value -is [decimal] -or $Value -is [single]) { return [int][Math]::Round([double]$Value,0) }
  $s = [string]$Value; if ([string]::IsNullOrWhiteSpace($s)) { if ($AllowNull){return $null} throw "As-Int: Empty string" }
  $s=$s.Trim()
  if ($s -match '^\s*0x[0-9A-Fa-f]+\s*$') { return [int][Convert]::ToInt64($s,16) }
  $s2 = ($s -replace '[,_\s]', '')
  if ($s2 -ieq 'true')  { return 1 }
  if ($s2 -ieq 'false') { return 0 }
  if ($s2 -match '^-?\d+\.\d+$') { return [int][Math]::Round([double]$s2,0) }
  if ($s2 -match '^-?\d+$')      { return [int]$s2 }
  if ($Value -is [System.Collections.IEnumerable] -and -not ($Value -is [string])) {
    $out=@(); foreach($i in $Value){ $out += (As-Int -Value $i -AllowNull:$AllowNull.IsPresent) }
    if ($out.Count -eq 1){ return [int]$out[0] }
    return [int]$out.Count
  }
  throw "As-Int: Cannot coerce '$Value'"
}
Export-ModuleMember -Function As-Int

