param([string]$PlansDir="pages/apps/carol/plans",[string]$OutFile="pages/apps/carol/plans/shopping-extracted.json")
$ErrorActionPreference="Stop"
$here = Split-Path -Parent $PSScriptRoot
$plansAbs = Join-Path $here $PlansDir
$outAbs = Join-Path $here $OutFile
if(-not (Test-Path $plansAbs)){ Write-Error "PlansDir not found: $plansAbs"; exit 1 }
function Load-Json($p){ try { Get-Content -Raw -Path $p | ConvertFrom-Json -ErrorAction Stop } catch { $null } }
function Norm([string]$s){ if($null -eq $s){ return $null }; return $s.Trim() }
function CanonUnit([string]$u){
  if($null -eq $u){ return $null }; $u=$u.ToLower().Trim()
  switch($u){
    "tablespoon" {"tbsp"} "tbs" {"tbsp"} "tbsp" {"tbsp"}
    "teaspoon" {"tsp"} "tsp" {"tsp"}
    "cup" {"cups"} "cups" {"cups"}
    "ct" {"ct"} "count" {"ct"}
    "oz" {"oz"} "ounce" {"oz"} "ounces" {"oz"}
    "fl oz" {"fl_oz"} "floz" {"fl_oz"}
    "ml" {"ml"} "g" {"g"} default { $u }
  }
}
$ctNames = @("eggs","rice cakes","tortillas","romaine","romaine hearts")
function Push-Item([ref]$acc, [double]$qty, [string]$unit, [string]$name){
  if($qty -le 0){ return }; $unit = CanonUnit $unit; $name = Norm $name; if([string]::IsNullOrWhiteSpace($name)){ return }
  if($unit -eq "g"){ $qty = [math]::Round(($qty / 28.3495), 2); $unit = "oz" }
  elseif($unit -eq "ml"){ $qty = [math]::Round(($qty / 29.5735), 2); $unit = "fl_oz" }
  elseif($null -eq $unit -or $unit -eq ""){ foreach($t in $ctNames){ if($name.ToLower().Contains($t)){ $unit="ct"; break } }; if($null -eq $unit){ $unit="ct" } }
  $acc.Value += @{ name=$name; qty=[double]$qty; unit=$unit }
}
function Parse-Freeform([string]$s){
  $s=$s.Trim(); $m=[regex]::Match($s,'^\s*(\d+(?:\.\d+)?)\s*([a-zA-Z ]+)?\s+(.+?)\s*$')
  if($m.Success){ $qty=[double]$m.Groups[1].Value; $unit=$m.Groups[2].Value.Trim(); if($unit -eq ""){ $unit=$null }; $name=$m.Groups[3].Value.Trim(); return ,(@{qty=$qty; unit=$unit; name=$name}) } else { return @() }
}
function Harvest-Node([ref]$acc, $node){
  if($null -eq $node){ return }
  if($node -is [string]){ $c=Parse-Freeform $node; foreach($ci in $c){ Push-Item ([ref]$acc.Value) $ci.qty $ci.unit $ci.name }; return }
  if($node -is [System.Array]){ foreach($x in $node){ Harvest-Node ([ref]$acc.Value) $x }; return }
  if($node.PSObject.Properties['shopping']){ Harvest-Node ([ref]$acc.Value) $node.shopping }
  if($node.PSObject.Properties['ingredients']){ foreach($ing in $node.ingredients){ if($ing -is [string]){ $c=Parse-Freeform $ing; foreach($ci in $c){ Push-Item ([ref]$acc.Value) $ci.qty $ci.unit $ci.name } } else { $q=$ing.qty; $u=$ing.unit; $n=$ing.name; if(-not $n){ $n=$ing.item }; if($q -and $n){ Push-Item ([ref]$acc.Value) $q $u $n } } } }
  foreach($key in @('meals','entries','items','snacks','breakfast','lunch','dinner','snack1','snack2','snack3')){ if($node.PSObject.Properties[$key]){ Harvest-Node ([ref]$acc.Value) $node.$key } }
}
$items = @()
$files = Get-ChildItem -Path $plansAbs -File -Filter "*.json" | Where-Object { $_.Name -notmatch "^shopping-(extracted|quantized)\.json$" -and $_.Name -notmatch "^packages-missing\.json$" }
foreach($f in $files){
  $j = Load-Json $f.FullName; if($null -eq $j){ continue }
  if($j.shopping){ Harvest-Node ([ref]$items) $j.shopping }
  if($j.menu){ if($j.menu.shopping){ Harvest-Node ([ref]$items) $j.menu.shopping }; if($j.menu.days){ foreach($d in $j.menu.days){ if($d.shopping){ Harvest-Node ([ref]$items) $d.shopping } else { Harvest-Node ([ref]$items) $d } } } }
  elseif($j.days){ foreach($d in $j.days){ if($d.shopping){ Harvest-Node ([ref]$items) $d.shopping } else { Harvest-Node ([ref]$items) $d } } }
}
$flat=@(); foreach($x in $items){ $n=$x.name; if(-not $n){ $n=$x.item }; $u=$x.unit; $q=$x.qty; if($n -and $q){ $flat += @{ name=$n; qty=[double]$q; unit=$u } } }
$doc=@{ updated=(Get-Date).ToUniversalTime().ToString("s")+"Z"; items=$flat }
$dir = Split-Path -Parent $outAbs; if(-not (Test-Path $dir)){ New-Item -ItemType Directory -Force -Path $dir | Out-Null }
[IO.File]::WriteAllText($outAbs, ($doc | ConvertTo-Json -Depth 6), [Text.Encoding]::UTF8)

param(
  [string]$PlansDir="pages/apps/carol/plans",
  [string]$OutFile="pages/apps/carol/plans/shopping-extracted.json"
)
$ErrorActionPreference = "Stop"
$root = Split-Path -Parent $PSScriptRoot
$plansAbs = Join-Path $root $PlansDir
$outAbs = Join-Path $root $OutFile

if(-not (Test-Path $plansAbs)){ Write-Error "PlansDir not found: $plansAbs"; exit 1 }
$files = Get-ChildItem -Path $plansAbs -File -Filter "*.json" | Sort-Object LastWriteTime -Descending
if(-not $files){ Write-Error "No *.json plans found in $plansAbs"; exit 1 }
$chosen = $files[0]

try{ $j = Get-Content -Raw -Path $chosen.FullName | ConvertFrom-Json }
catch{ Write-Error "Invalid JSON in $($chosen.Name)"; exit 1 }

# Prefer explicit shopping arrays if present
$shopping = @()
if($j.shopping){ $shopping = $j.shopping }
elseif($j.menu -and $j.menu.shopping){ $shopping = $j.menu.shopping }

function Add-Item($list, [string]$name, [double]$qty, [string]$unit){
  if([string]::IsNullOrWhiteSpace($name)){ return }
  if([string]::IsNullOrWhiteSpace($unit)){ $unit = "" }
  $already = $list | Where-Object { $_.name -eq $name -and $_.unit -eq $unit } | Select-Object -First 1
  if($already){ $already.qty += $qty }
  else { $list += ([pscustomobject]@{ name=$name; qty=$qty; unit=$unit }) }
  return $list
}

function Try-Extract-Node([object]$node, [ref]$acc){
  if($null -eq $node){ return }
  if($node -is [pscustomobject] -or $node -is [hashtable]){
    $n = $null; $q = $null; $u = $null
    if($node.PSObject.Properties.Name -contains 'name'){ $n = [string]$node.name }
    foreach($k in @('qty','quantity')){ if($node.PSObject.Properties.Name -contains $k){ $q = [double]$node.$k; break } }
    foreach($k in @('unit','units')){ if($node.PSObject.Properties.Name -contains $k){ $u = [string]$node.$k; break } }
    if($n -and ($q -ne $null)){ $acc.Value = Add-Item -list $acc.Value -name $n -qty $q -unit $u }
    foreach($p in $node.PSObject.Properties){ Try-Extract-Node $p.Value ([ref]$acc.Value) }
  } elseif($node -is [System.Collections.IEnumerable]){
    foreach($x in $node){ Try-Extract-Node $x ([ref]$acc.Value) }
  }
}

if($shopping.Count -eq 0){
  $acc = @()
  Try-Extract-Node $j ([ref]$acc)
  $shopping = $acc
}

$payload = @{
  updated=(Get-Date).ToUniversalTime().ToString('s')+'Z';
  source_plan=$chosen.Name;
  count=$shopping.Count;
  items=$shopping
}
$dirOut = Split-Path -Parent $outAbs
if(-not (Test-Path $dirOut)){ New-Item -ItemType Directory -Force -Path $dirOut | Out-Null }
[IO.File]::WriteAllText($outAbs, ($payload | ConvertTo-Json -Depth 6), [Text.Encoding]::UTF8)
Write-Host "Extracted shopping items -> $OutFile (from $($chosen.Name))"

param(
  [string]$OutFile="pages/apps/carol/plans/packages-missing.json",
  [string]$ShoppingFile="pages/apps/carol/plans/shopping-extracted.json",
  [string]$PackageMap="pages/apps/carol/packages/us.json"
)
$ErrorActionPreference="Stop"
$root = Split-Path -Parent $PSScriptRoot
$outAbs = Join-Path $root $OutFile
$sfAbs = Join-Path $root $ShoppingFile
$mapAbs = Join-Path $root $PackageMap

if(-not (Test-Path $sfAbs)){ Write-Error "No shopping-extracted.json found or empty. Run Extract first."; exit 1 }
if(-not (Test-Path $mapAbs)){ Write-Error "Package map not found at $mapAbs"; exit 1 }

$doc = Get-Content -Raw -Path $sfAbs | ConvertFrom-Json
$items = $doc.items
$map = Get-Content -Raw -Path $mapAbs | ConvertFrom-Json

function Find-Sku([string]$name){
  if([string]::IsNullOrWhiteSpace($name)){ return $null }
  $k = $name.ToLowerInvariant()
  if($map.ingredient_map.PSObject.Properties.Name -contains $k){ return [string]$map.ingredient_map.$k }
  foreach($kk in $map.ingredient_map.PSObject.Properties.Name){ if($k -like "*$kk*"){ return [string]$map.ingredient_map.$kk } }
  return $null
}

$missing = @()
foreach($it in $items){
  $n=[string]$it.name; if([string]::IsNullOrWhiteSpace($n)){ continue }
  $sku = Find-Sku $n
  if(-not $sku){
    $example = ('"{0}": "<sku_key>"' -f $n.ToLowerInvariant())
    $missing += @{ name=$n; suggestion="Add to ingredient_map"; example=$example }
  }
}

$report = @{ updated=(Get-Date).ToUniversalTime().ToString('s')+'Z'; missing=$missing }
$dirOut = Split-Path -Parent $outAbs
if(-not (Test-Path $dirOut)){ New-Item -ItemType Directory -Force -Path $dirOut | Out-Null }
[IO.File]::WriteAllText($outAbs, ($report | ConvertTo-Json -Depth 6), [Text.Encoding]::UTF8)
Write-Host "Wrote $OutFile with $($missing.Count) unmapped items."

param([string]$PlansDir="pages/apps/carol/plans")
$ErrorActionPreference="Stop"
$here = Split-Path -Parent $PSScriptRoot
$plansAbs = Join-Path $here $PlansDir
if(-not (Test-Path $plansAbs)){ Write-Error "PlansDir not found: $plansAbs"; exit 1 }
$shoppingExtracted = Join-Path $plansAbs "shopping-extracted.json"
if(Test-Path $shoppingExtracted){
  $doc = Get-Content -Raw -Path $shoppingExtracted | ConvertFrom-Json
  $arr = if($doc.items){ $doc.items } else { $doc.shopping }
  if($arr){ Write-Host "shopping-extracted.json items: $($arr.Count)"; return }
}
$files = Get-ChildItem -Path $plansAbs -File -Filter "*.json" | Where-Object {
  $_.Name -notmatch "^shopping-(extracted|quantized)\.json$" -and $_.Name -notmatch "^packages-missing\.json$"
}
$found=0
foreach($f in $files){
  try{
    $j = Get-Content -Raw -Path $f.FullName | ConvertFrom-Json
    if($j.shopping){ Write-Host "$($f.Name): shopping[] = $($j.shopping.Count)"; $found++ }
    elseif($j.menu -and $j.menu.shopping){ Write-Host "$($f.Name): menu.shopping[] = $($j.menu.shopping.Count)"; $found++ }
    elseif($j.menu -and $j.menu.days){ Write-Host "$($f.Name): menu.days[] present (run Extract v2)" }
    else{ Write-Host "$($f.Name): no shopping array" }
  } catch {
    Write-Host "$($f.Name): JSON parse error"
  }
}
if($found -eq 0){ Write-Host "No plan JSONs with shopping array found. Run Extract v2 to build shopping-extracted.json." }

$root = Split-Path -Parent $PSScriptRoot
$dir  = Join-Path $root 'pages/apps/carol/plans'
if (-not (Test-Path $dir)) { Write-Host "No Carol plans."; exit 0 }
$bad=@(); $warn=@()
Get-ChildItem -File $dir -Filter *.json | ForEach-Object {
  $p = Get-Content -Raw -Path $_.FullName | ConvertFrom-Json
  if (-not $p.sources -or $p.sources.Count -lt 1) { $bad += @{file=$_.Name; issue="no-sources"} }
  foreach($d in $p.days){
    $sodium = 0; $sugar_g = 0; $kcal = 0; $fiber = 0
    foreach($m in $d.menus){ $sodium += ($m.sodium_mg|Measure-Object -Sum).Sum; $sugar_g += ($m.added_sugars_g|Measure-Object -Sum).Sum; $kcal += ($m.est_kcal|Measure-Object -Sum).Sum; $fiber += ($m.fiber_g|Measure-Object -Sum).Sum }
    if ($sodium -gt 2000) { $bad += @{file=$_.Name; day=$d.day; issue=("sodium>"+$sodium)} }
    if ($kcal -gt 0) {
      $sugar_pct = (($sugar_g*4.0)/[double]$kcal)*100.0
      if ($sugar_pct -gt 10.0) { $bad += @{file=$_.Name; day=$d.day; issue=("added_sugars%="+[math]::Round($sugar_pct,1))} }
    } else { $warn += @{file=$_.Name; day=$d.day; issue="missing_kcal_for_%calc"} }
    if ($fiber -lt 25) { $warn += @{file=$_.Name; day=$d.day; issue=("fiber_low="+$fiber)} }
  }
}
if ($bad.Count -gt 0) { Write-Error ("Carol validate failed: " + ($bad | ConvertTo-Json -Depth 6)); exit 1 }
Write-Host ("Carol validate OK. Warnings: " + ($warn | ConvertTo-Json -Depth 6))

