function Sha256Hex([byte[]]$bytes){ $sha=[System.Security.Cryptography.SHA256]::Create(); $h=$sha.ComputeHash($bytes); ($h|ForEach-Object ToString X2) -join "" }
$rows=@()
$files = Get-ChildItem -Path $repo -Recurse -File -Force | Where-Object { $_.FullName -notmatch "\\.git(\\|/)" }
foreach($f in $files){
  try{
    $rel = "/"+($f.FullName.Replace($repo,"").TrimStart('\','/').Replace('\','/'))
    $b = [IO.File]::ReadAllBytes($f.FullName)
    $sha = Sha256Hex $b
    $textPreview = $null
    if($f.Length -le $MaxPreview){
      try{ $textPreview = [Text.Encoding]::UTF8.GetString($b) } catch { $textPreview = $null }
    }
    $rows += @{ path=$rel; size=$f.Length; sha256=$sha; preview=$textPreview }
  } catch {}
}
$out = @{ updated=(Get-Date).ToUniversalTime().ToString("s")+"Z"; count=$rows.Count; files=$rows }
$outPath = Join-Path $here "memory-history/repo-read-index.json"
$dir = Split-Path -Parent $outPath; if(-not (Test-Path $dir)){ New-Item -ItemType Directory -Force -Path $dir | Out-Null }
[IO.File]::WriteAllText($outPath, ($out | ConvertTo-Json -Depth 4), [Text.Encoding]::UTF8)
