name: Avalon: Run-All
on:
  workflow_dispatch:
    inputs:
      worlds: { description: 'Worlds', default: 1, type: number }
      run_llm_bridge: { description: 'Alexandria LLM', default: true, type: boolean }
      run_carol_llm: { description: 'Carol', default: true, type: boolean }
      run_jem_llm: { description: 'Jem', default: true, type: boolean }
      run_stella_llm: { description: 'Stella', default: true, type: boolean }
      run_tts: { description: 'Charlotte TTS (OpenAI)', default: false, type: boolean }
jobs:
  run-all:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - name: Run-All (scaffolds)
        shell: pwsh
        run: pwsh -File scripts/Run-All.ps1 -WorldCount ${{ inputs.worlds }} -NonInteractive true
      - name: Alexandria LLM Bridge
        if: ${{ inputs.run_llm_bridge == true }}
        env: { OPENAI_API_KEY: ${{ secrets.OPENAI_API_KEY }}, OPENAI_MODEL: ${{ vars.OPENAI_MODEL }} }
        shell: pwsh
        run: pwsh -File scripts/LLM-Bridge.ps1 -WorldsToGenerate ${{ inputs.worlds }}
      - name: Carol LLM Plans
        if: ${{ inputs.run_carol_llm == true }}
        env: { OPENAI_API_KEY: ${{ secrets.OPENAI_API_KEY }}, OPENAI_MODEL: ${{ vars.OPENAI_MODEL }} }
        shell: pwsh
        run: pwsh -File scripts/Carol-Diet-LLM.ps1 -Pattern DASH -Kcal 2200 -Region EU -Context truck_driver
      - name: Jem LLM Programs
        if: ${{ inputs.run_jem_llm == true }}
        env: { OPENAI_API_KEY: ${{ secrets.OPENAI_API_KEY }}, OPENAI_MODEL: ${{ vars.OPENAI_MODEL }} }
        shell: pwsh
        run: pwsh -File scripts/Jem-Training-LLM.ps1 -Goal hypertrophy -Experience novice -WeeklySessions 5 -Context truck_driver -MaxSessionMin 20
      - name: Stella LLM Components
        if: ${{ inputs.run_stella_llm == true }}
        env: { OPENAI_API_KEY: ${{ secrets.OPENAI_API_KEY }}, OPENAI_MODEL: ${{ vars.OPENAI_MODEL }} }
        shell: pwsh
        run: pwsh -File scripts/Agents-LLM.ps1 -Agent 'Stella' -Count 5 -Task 'design guided audio session outlines (non-therapeutic)'
      - name: Charlotte TTS (OpenAI) (optional)
        if: ${{ inputs.run_tts == true }}
        env: { OPENAI_API_KEY: ${{ secrets.OPENAI_API_KEY }}, OPENAI_MODEL: ${{ vars.OPENAI_MODEL }} }
        shell: pwsh
        run: pwsh -File scripts/Charlotte-TTS-OpenAI.ps1
      - name: Commit generated content
        shell: bash
        run: |
          set -e
          git config user.name "github-actions[bot]"
          git config user.email "github-actions[bot]@users.noreply.github.com"
          git add pages/
          if git diff --cached --quiet; then echo "No changes";
          else git commit -m "chore(run-all): update generated content (all AI)"; git push; fi

