name: Overseers — Asset Audit
on: { workflow_dispatch: {} }
jobs:
  asset-audit:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - name: Count assets and sizes
        shell: pwsh
        run: |
          $root = Get-Location
          $paths = @{
            models = 'asset/models'
            winged = 'asset/winged-models'
            wings  = 'asset/wings'
            wingtex = 'asset/wings/textures'
            walls = 'asset/textures/wallpapers'
          }
          function Stat-Path($p){
            $o = @{ path=$p; files=0; bytes=0 }
            if (Test-Path $p) {
              Get-ChildItem -Recurse -File $p | ForEach-Object { $o.files++; $o.bytes += $_.Length }
            } else { $o.missing = $true }
            return $o
          }
          $report = [ordered]@{ generated=(Get-Date).ToUniversalTime().ToString('s')+'Z'; items=@{} }
          foreach ($k in $paths.Keys) { $report.items[$k] = Stat-Path $paths[$k] }
          $outDir = 'pages/diagnostics'
          New-Item -ItemType Directory -Path $outDir -Force | Out-Null
          $json = $report | ConvertTo-Json -Depth 8
          Set-Content -Path (Join-Path $outDir 'progress.json') -Value $json -NoNewline -Encoding utf8
      - name: Commit audit
        shell: bash
        run: |
          git config user.name "github-actions[bot]"
          git config user.email "github-actions[bot]@users.noreply.github.com"
          git add pages/diagnostics/progress.json
          if git diff --cached --quiet; then echo "No changes"; else git commit -m "chore(audit): asset progress" && git push; fi

name: Overseers — Import-Map Check
on:
