  push:
    paths: [ 'index.html', 'pages/**.html', 'pages/**.js' ]
jobs:
  importmap-check:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - name: Verify import-map presence when modules used
        shell: pwsh
        run: |
          function Uses-Modules {
            param([string]$dir)
            $patterns = @('type="module"','from "three"','from ''three''','@pixiv/three-vrm')
            $files = Get-ChildItem -Recurse -File $dir -Include *.html,*.js -ErrorAction SilentlyContinue
            foreach($f in $files){
              $t = Get-Content -Raw -Path $f.FullName
              foreach($p in $patterns){ if ($t -match [regex]::Escape($p)) { return $true } }
            }
            return $false
          }
          $needsMap = (Uses-Modules -dir '.')
          if (-not $needsMap) { Write-Host "No module usage detected. OK."; exit 0 }
          if (-not (Test-Path 'index.html')){ Write-Error 'index.html missing'; exit 1 }
          $idx = Get-Content -Raw -Path 'index.html'
          if ($idx -notmatch 'type="importmap"') {
            Write-Error 'Module usage detected but <script type="importmap"> not found in index.html'
            exit 1
          }
          Write-Host 'Import-map present. OK.'

