*{box-sizing:border-box}body{margin:0;font-family:system-ui;background:var(--bg);color:var(--ink)}
header,footer{padding:12px 16px;border-bottom:1px solid var(--line)}
main{padding:16px}
.grid{display:grid;gap:12px;grid-template-columns:repeat(auto-fit,minmax(260px,1fr))}
.card{border:1px solid var(--line);background:var(--card);border-radius:12px;padding:12px}
.hero h1{margin:0;padding:10px 14px;background:#0b1220A0;display:inline-block;border-radius:10px;border:1px solid #172033}
.kv{display:flex;flex-direction:column;gap:6px}.kv b{display:block;color:#93c5fd}
.btn{display:inline-block;padding:8px 10px;border:1px solid #334155;border-radius:10px;color:var(--ink);text-decoration:none;background:#0b1220}
.btn:hover{border-color:#3b82f6;color:white}
iframe.viewer{width:100%;height:60vh;border:1px solid #172033;border-radius:12px;background:#0b1220}
.small{font-size:12px;color:#9ca3af}
.room{min-height:28vh}

